package com.yeyamo_mobile.api.feed_service.infrastructure.persistence;import java.time.Instant;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Component;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.feed_service.application.port.FeedProjectionPort;import com.yeyamo_mobile.api.feed_service.domain.model.*;
@Component public class JpaFeedProjectionAdapter implements FeedProjectionPort{private final SpringFeedPostRepository posts;private final SpringFeedMetricRepository metrics;private final SpringFeedSignalRepository signals;private final ObjectMapper mapper;public JpaFeedProjectionAdapter(SpringFeedPostRepository p,SpringFeedMetricRepository m,SpringFeedSignalRepository s,ObjectMapper o){posts=p;metrics=m;signals=s;mapper=o;}
 public void savePost(FeedPost p){try{FeedPostEntity e=posts.findById(p.postId()).orElseGet(FeedPostEntity::new);e.setPostId(p.postId());e.setAuthorId(p.authorId());e.setCaption(p.caption());e.setVisibility(p.visibility());e.setStatus(p.status());e.setCatalogAssetId(p.catalogAssetId());e.setReferenceType(p.referenceType());e.setReferenceId(p.referenceId());e.setMediaIds(mapper.writeValueAsString(p.mediaIds()));e.setHashtags(mapper.writeValueAsString(p.hashtags()));e.setAvailable(p.available());e.setPublishedAt(p.publishedAt());e.setUpdatedAt(p.updatedAt());posts.save(e);}catch(Exception e){throw new IllegalStateException("Cannot save feed post projection",e);}}
 public Optional<FeedPost>findPost(UUID id){return posts.findById(id).map(this::post);}public FeedMetric metric(UUID id){return metrics.findById(id).map(this::metric).orElseGet(()->FeedMetric.empty(id));}public void saveMetric(FeedMetric m){FeedMetricEntity e=metrics.findById(m.postId()).orElseGet(FeedMetricEntity::new);e.setPostId(m.postId());e.setLikes(m.likes());e.setComments(m.comments());e.setShares(m.shares());e.setFavorites(m.favorites());e.setUpdatedAt(m.updatedAt());metrics.save(e);}
 public void adjustSignal(String user,UUID post,double weight){FeedSignalEntity e=signals.findByUserIdAndPostId(user,post).orElseGet(()->{var n=new FeedSignalEntity();n.setId(UUID.randomUUID());n.setUserId(user);n.setPostId(post);n.setWeight(0);return n;});e.setWeight(Math.max(0,e.getWeight()+weight));e.setUpdatedAt(Instant.now());signals.save(e);}
 public List<FeedCandidate>candidates(int limit){List<FeedPostEntity>p=posts.findByAvailableTrueOrderByPublishedAtDesc(PageRequest.of(0,limit));Map<UUID,FeedMetricEntity>m=new HashMap<>();metrics.findAllById(p.stream().map(FeedPostEntity::getPostId).toList()).forEach(v->m.put(v.getPostId(),v));return p.stream().map(v->new FeedCandidate(post(v),m.containsKey(v.getPostId())?metric(m.get(v.getPostId())):FeedMetric.empty(v.getPostId()))).toList();}
 public Map<String,Double>authorAffinities(String user){Map<String,Double>r=new HashMap<>();signals.authorAffinities(user).forEach(v->r.put((String)v[0],((Number)v[1]).doubleValue()));return r;}
 private FeedPost post(FeedPostEntity e){try{return new FeedPost(e.getPostId(),e.getAuthorId(),e.getCaption(),e.getVisibility(),e.getStatus(),e.getCatalogAssetId(),e.getReferenceType(),e.getReferenceId(),mapper.readValue(e.getMediaIds(),new TypeReference<List<UUID>>(){}),mapper.readValue(e.getHashtags(),new TypeReference<List<String>>(){}),e.getPublishedAt(),e.getUpdatedAt());}catch(Exception x){throw new IllegalStateException("Invalid feed post projection",x);}}private FeedMetric metric(FeedMetricEntity e){return new FeedMetric(e.getPostId(),e.getLikes(),e.getComments(),e.getShares(),e.getFavorites(),e.getUpdatedAt());}}
